function remapWeekEntries(map, moves) {
  const original = new Map(map);
  for (const key of original.keys()) {
    const week = Number(key.split('-')[0]);
    if (week >= 7 && week <= 12) map.delete(key);
  }
  for (const [targetWeek, sourceWeek] of moves) {
    for (let day = 1; day <= 5; day += 1) {
      const value = original.get(`${sourceWeek}-${day}`);
      if (value !== undefined) map.set(`${targetWeek}-${day}`, value);
    }
  }
}

