function caseFor(week, day) {
  const reviewed = reviewedCases.get(`${week}-${day}`);
  if (reviewed) {
    const [answer, code, lines, bad, fix] = reviewed;
    const comment = week === 22 || week === 23 || week === 24 || (week === 25 && [2, 4].includes(day)) ? '#' : '//';
    const label = `${comment} ${topics[week - 1]} · ${concepts[week - 1][day - 1]}`;
    return { answer, code: `${label}\n${code}`, lines: [label, ...lines], bad: bad + 1, fix };
  }
  const concept = concepts[week - 1][day - 1];
  const topic = topics[week - 1];
  // Week 6 onward cannot reuse a weekday's unrelated injection/configuration
  // sample.  This is a deliberately small, runnable-looking contract review:
  // the named Spring concept is absent from a boundary that claims to apply it.
  // The highlighted line is the real defect, rather than a generic password or
  // controller error relabelled with a different answer.
  return {
    answer: concept,
    code: `// ${topic} · ${concept}\nclass CourseBoundary {\n  void apply() {\n    throw new UnsupportedOperationException("${concept} is not applied");\n  }\n}`,
    lines: [
      `// ${topic} · ${concept}`,
      'class CourseBoundary {',
      '  void apply() {',
      `    throw new UnsupportedOperationException("${concept} is not applied");`,
      '  }',
      '}',
    ],
    bad: 4,
    fix: `${topic} 경계에서 ${concept}을(를) 실제 구성·요청 계약·테스트에 적용하고, 이 임시 예외를 제거해야 합니다.`,
  };
}
